import{_ as a,o as i,c as o,a2 as s}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Buenas practicas","description":"","frontmatter":{},"headers":[],"relativePath":"ia/ollama/07-buenas-practicas.md","filePath":"ia/ollama/07-buenas-practicas.md","lastUpdated":1789040978000,"isDraft":false}'),t={name:"ia/ollama/07-buenas-practicas.md"};function l(n,e,r,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="buenas-practicas" tabindex="-1">Buenas practicas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas practicas&quot;">​</a></h1><p>Este capitulo cierra el manual con criterios de seguridad, reproducibilidad y operacion. Ollama es simple de arrancar; el riesgo aparece al exponerlo, mezclar modelos o no fijar versiones.</p><h2 id="seguridad-basica" tabindex="-1">Seguridad basica <a class="header-anchor" href="#seguridad-basica" aria-label="Permalink to &quot;Seguridad basica&quot;">​</a></h2><ul><li>Por defecto escucha en localhost: mantenlo asi salvo necesidad clara.</li><li>Si expones la API en una red, pon reverse proxy con autenticacion (no dejes <code>:11434</code> abierto a Internet).</li><li>No envies secretos en prompts que luego logueas enteros.</li><li>Separa entornos: el Ollama de desarrollo no debe ver datos de produccion reales sin control.</li><li>Revisa licencia del modelo antes de uso comercial (<code>ollama show</code> / ficha en la libreria).</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Escuchar solo en loopback (ejemplo)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> OLLAMA_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1:11434</span></span></code></pre></div><h2 id="versionado-reproducible" tabindex="-1">Versionado reproducible <a class="header-anchor" href="#versionado-reproducible" aria-label="Permalink to &quot;Versionado reproducible&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Que fijar</th><th>Como</th></tr></thead><tbody><tr><td>Ollama</td><td>Version en README / imagen Docker</td></tr><tr><td>Modelo</td><td>Tag explicito (<code>llama3.2:1b</code>)</td></tr><tr><td>Prompt de sistema</td><td>Modelfile en git</td></tr><tr><td>Cliente</td><td>Pin de libreria (<code>ollama==x.y.z</code>)</td></tr></tbody></table><p>Tras un <code>pull</code>, guarda salida de:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:1b</span></span></code></pre></div><p>En equipos, un <code>Modelfile</code> compartido evita &quot;en mi maquina responde distinto&quot;.</p><h2 id="diseno-de-prompts-y-modelos" tabindex="-1">Diseno de prompts y modelos <a class="header-anchor" href="#diseno-de-prompts-y-modelos" aria-label="Permalink to &quot;Diseno de prompts y modelos&quot;">​</a></h2><ul><li>Un modelo por responsabilidad: chat, codigo, embeddings, vision.</li><li>System prompts cortos y testeables; evita novelas en <code>SYSTEM</code>.</li><li>Para salidas estructuradas usa <code>format: json</code> + schema validado en codigo.</li><li>Recorta historial: resumen o ventana deslizante antes de saturar <code>num_ctx</code>.</li><li>Evalua con un set fijo de 10–20 preguntas de tu dominio.</li></ul><h2 id="operacion-diaria" tabindex="-1">Operacion diaria <a class="header-anchor" href="#operacion-diaria" aria-label="Permalink to &quot;Operacion diaria&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arrancar daemon -&gt; healthcheck /api/tags -&gt; calentar modelo -&gt; servir trafico</span></span></code></pre></div><p>Checklist:</p><ol><li><code>ollama list</code> tiene los modelos necesarios.</li><li>Healthcheck OK antes de marcar el pod/servicio healthy.</li><li><code>keep_alive</code> acorde al trafico (ni descarga constante ni VRAM siempre llena sin uso).</li><li>Logs de latencia y errores de conexion en la app cliente.</li><li>Politica de limpieza: <code>ollama rm</code> de experimentos viejos.</li></ol><h2 id="recursos-y-coste" tabindex="-1">Recursos y coste <a class="header-anchor" href="#recursos-y-coste" aria-label="Permalink to &quot;Recursos y coste&quot;">​</a></h2><p>Aunque no pagues por token, pagas en:</p><ul><li>Disco (varios GB por modelo).</li><li>Electricidad / tiempo de GPU.</li><li>Latencia de usuario.</li></ul><p>Politica sana: modelos pequenos en CI y demos; modelo mayor solo en el entorno que lo necesita.</p><h2 id="integracion-con-rag-y-agentes" tabindex="-1">Integracion con RAG y agentes <a class="header-anchor" href="#integracion-con-rag-y-agentes" aria-label="Permalink to &quot;Integracion con RAG y agentes&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Embeddings (nomic-embed-text) -&gt; vector store -&gt; contexto -&gt; chat model (llama/mistral)</span></span></code></pre></div><ul><li>Mismo embedding para indexado y query.</li><li>Limita fragmentos inyectados (top-K) para no hinchar el prompt.</li><li>El Modelfile del chat debe instruir a basarse en el contexto proporcionado.</li></ul><h2 id="anti-patrones" tabindex="-1">Anti-patrones <a class="header-anchor" href="#anti-patrones" aria-label="Permalink to &quot;Anti-patrones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Evitar</th><th>Preferir</th></tr></thead><tbody><tr><td><code>latest</code> sin pin en produccion</td><td>Tag concreto + nota de upgrade</td></tr><tr><td>Un unico prompt gigante para todo</td><td>Modelfiles por caso de uso</td></tr><tr><td>API publica sin auth</td><td>Localhost o proxy autenticado</td></tr><tr><td>Ignorar OOM / swaps</td><td>Modelo que cabe en VRAM/RAM</td></tr><tr><td>Cambiar modelo sin re-probar</td><td>Suite de prompts de regresion</td></tr></tbody></table><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Desplegar en cloud con disco efimero y perder los modelos en cada restart (usa volumen persistente).</li><li>Mezclar respuestas de modelos distintos en la misma sesion de usuario sin indicarlo.</li><li>Loguear prompts completos con PII.</li><li>Asumir que <code>format: json</code> garantiza schema: siempre valida en codigo.</li><li>No documentar hardware minimo del proyecto.</li></ul><h2 id="checklist-final-del-manual" tabindex="-1">Checklist final del manual <a class="header-anchor" href="#checklist-final-del-manual" aria-label="Permalink to &quot;Checklist final del manual&quot;">​</a></h2><ul><li>[ ] Ollama instalado y <code>ollama run</code> funciona.</li><li>[ ] Modelo de chat + embeddings descargados con tags fijos.</li><li>[ ] Al menos un Modelfile versionado.</li><li>[ ] Cliente Python o JS con host configurable.</li><li>[ ] Medicion basica de latencia (<code>eval_duration</code> / tokens/s).</li><li>[ ] API no expuesta sin proteccion.</li><li>[ ] README con comandos <code>pull</code>, <code>create</code> y variables de entorno.</li></ul><h2 id="ejercicios" tabindex="-1">Ejercicios <a class="header-anchor" href="#ejercicios" aria-label="Permalink to &quot;Ejercicios&quot;">​</a></h2><ol><li>Escribe un README de 15 lineas para un servicio que use Ollama (install, pull, env).</li><li>Crea dos Modelfiles (clasificador vs redactor) y documenta cuando usar cada uno.</li><li>Anade un healthcheck HTTP en tu app que falle si <code>/api/tags</code> no responde.</li><li>Define un set de 5 prompts de regresion y ejecutalos tras cambiar de modelo.</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Con el manual completo puedes montar un asistente local, un pipeline RAG o un backend compatible OpenAI. Si vas a retrieval, combina este material con el manual de RAG del repositorio (<code>ia/rag/</code>).</p>`,33)])])}const m=a(t,[["render",l]]);export{h as __pageData,m as default};
